        Colors[0] := 'FF0000'; // clRed
        Colors[1] := 'FF7700'; // clOrange
        Colors[2] := '0044FF'; // clLightBlue
        Colors[3] := '00BB00'; // clGreen
        Colors[4] := 'FFFF00'; // clYellow
        Colors[5] := 'FFFFFF'; // clWhite

        W := 0.5;
        include 'Figures\Scripts\Cube_Coordinates.inc';

        Delta := 1.001;
        D := W * 0.21;

        R1 := W * 0.8;
        R2 := W * 0.6;
        R3 := W * 0.4;
        WC1 := W * Delta;
        WC2 := W * (Delta * 2 - 1);
        WC3 := W * (Delta * 3 - 2);
        D1 := (WC1 + WC2) / 2;
        D2 := (WC2 + WC3) / 2;
    

    // this is version with free core. For version with fixed core uncomment this line and comment next

    
        
        
        
    

    
        
            
            
            Inc(ax);
        

        // make center parts ordered from 0 to 6 corresponding to face number (for SetTextures)
        W0 := W; W := WC3; R := R3; include 'Figures\Scripts\Cube_Coordinates.inc'; // save W
        
        
        
        
        
        

        W := WC2; R := R2; include 'Figures\Scripts\Cube_Coordinates.inc';
        

        W := WC1; R := R1; include 'Figures\Scripts\Cube_Coordinates.inc';
        

        
        



